mapper.sql:
select inventory.*, sku.id as sku_id, sku.*, item.id as item_id, item.*, z.zone_name as zone_name, l.location_code as location_code from wms_inventory inventory inner join wms_item_sku sku on inventory.sku_id=sku.id inner join wms_item item on sku.item_id=item.id left join wms_zone z on inventory.zone_id=z.id left join wms_location l on inventory.location_id=l.id
item.item_name like concat('%', #{bo.itemName}, '%')
and item.item_code like concat('%', #{bo.itemCode}, '%')
and sku.sku_name like concat('%', #{bo.skuName}, '%')
and sku.sku_code like concat('%', #{bo.skuCode}, '%')
and item.item_category=#{bo.itemCategory}
and item.id=#{bo.itemId}
and inventory.warehouse_id=#{bo.warehouseId}
and inventory.zone_id=#{bo.zoneId}
and inventory.quantity>=#{bo.minQuantity}

mapper.select:


    sku.safety_stock is not null
    and inventory.quantity < sku.safety_stock
     and inventory.warehouse_id = #{warehouseId}
     and inventory.zone_id = #{zoneId}
     and item.item_name like concat('%', #{itemName}, '%')

order by (sku.safety_stock - inventory.quantity) desc



    sku.max_stock is not null
    and inventory.quantity > sku.max_stock
     and inventory.warehouse_id = #{warehouseId}
     and inventory.zone_id = #{zoneId}
     and item.item_name like concat('%', #{itemName}, '%')

order by (inventory.quantity - sku.max_stock) desc



    inventory.quantity > 0
     and inventory.warehouse_id = #{warehouseId}
     and inventory.zone_id = #{zoneId}
    and not exists (
        select 1 from wms_inventory_history h
        where h.sku_id = inventory.sku_id
        and h.warehouse_id = inventory.warehouse_id
        and h.create_time >= date_sub(now(), interval #{slowDays} day)
    )

order by inventory.quantity asc
